# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Text, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, IdentificationL18nMixin, CreatorMixin, TimestampMixin


class CompendiumCatPost(TimestampMixin, CreatorMixin, IdentificationL18nMixin, Base):
    __tablename__ = "compendium_cat_post"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    name: Mapped[str] = mapped_column(
        Text,
        nullable=False,
        description=(
            "Title of the editorial or blog post in English, displayed as the "
            "heading in listings and detail views."
        ),
    )
    main_photo_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("asset_agg_photo.id"),
        description=(
            "Optional foreign key to the hero/cover photo displayed at the "
            "top of the post. References asset_agg_photo.id."
        ),
    )
    post_type_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("core_ref_post_type.id"),
        nullable=False,
        description=(
            "Foreign key to the post type classification (e.g. blog, news, "
            "guide, trip report). References core_ref_post_type.id."
        ),
    )
